///|
async fn discard_created_workspace(state : Json) -> Unit {
  @async.protect_from_cancel(async fn() {
    try {
      @async.with_timeout(45000, async fn() {
        guard workspace(state) is Some(current) &&
          field(current, "uid") == field(state, "workspaceUid") else {
          return
        }
        if field(state, "orcaVolumeCleanup") is None {
          remember_volume_cleanup(state, current)
        }
        if field(state, "user") is Some(_) {
          @async.with_timeout(15000, async fn() { close_tunnel(state) }) catch {
            _ => {
              save_diagnostic(
                "create-cleanup-tunnel",
                "warning",
                error_type="tunnel_cleanup",
              )
              @stdio.stderr.write(
                "orca-env-devsy: warning: tunnel cleanup failed; continuing workspace deletion\n",
              )
            }
          }
        }
        ignore(
          devsy(
            state,
            [
              "workspace",
              "delete",
              required(state, "workspaceId"),
              "--ignore-not-found",
            ],
            "create-cleanup",
          ),
        )
        cleanup_orca_volume(state)
      })
      save_diagnostic("create-cleanup", "success")
    } catch {
      _ => {
        @stdio.stderr.write(
          "orca-env-devsy: warning: create cleanup failed; inspect the workspace with Devsy\n",
        )
        save_diagnostic("create-cleanup", "warning")
      }
    }
  })
}

///|
fn valid_workspace_id(id : String) -> Bool {
  id.length() > 0 &&
  id.length() <= 48 &&
  ((id[0] >= 'a' && id[0] <= 'z') || (id[0] >= '0' && id[0] <= '9')) &&
  id
  .to_array()
  .iter()
      guard value > 0 else {
        raise AdapterError(name + " must be positive milliseconds")
      }
      value
    }
  }
}

///|
fn connection_timeout_ms(state? : Json) -> Int32 raise {
  configured_timing_ms("ORCA_ENV_DEVSY_CONNECTION_TIMEOUT_MS", 60000, state?)
}

///|
fn connection_deadline() -> UInt64 raise {
  @env.now() + connection_timeout_ms().to_uint64()
}

///|
fn connection_timeout_message() -> String raise {
  let timeout = connection_timeout_ms()
  let duration = if timeout % 1000 == 0 {
    "\{timeout / 1000} seconds"
  } else {
    "\{timeout} ms"
  }
  "SSH and relay readiness timed out after " + duration
}

///|
fn create_connection_timeout_message() -> String raise {
  let timeout = connection_timeout_ms()
  let duration = if timeout % 1000 == 0 {
    "\{timeout / 1000} seconds"
  } else {
    "\{timeout} ms"
  }
  match create_recording.phase {
    "worktree-git-config" =>
      "Git promisor and branch-ref configuration timed out within the " +
      duration +
      " environment-creation deadline"
    "worktree-git-fetch" =>
      "Initial origin branch fetch timed out within the " +
      duration +
      " environment-creation deadline"
    _ => "SSH and relay readiness timed out after " + duration
  }
}

///|
fn monitor_delay(attempt : Int32) -> Int32 {
  match attempt {
    0 => 15000
    1 => 30000
    2 => 60000
    3 => 120000
    _ => 300000
  }
}

  ConnectionDeadline
}

///|
async fn[T] connection_timeout(deadline : UInt64, run : async () -> T) -> T {
  connection_timeout_for(deadline, run, creation=false)
}

///|
async fn[T] creation_timeout(deadline : UInt64, run : async () -> T) -> T {
  connection_timeout_for(deadline, run, creation=true)
}

///|
async fn[T] connection_timeout_for(
  deadline : UInt64,
  run : async () -> T,
  creation~ : Bool,
) -> T {
  let now = @env.now()
  if deadline <= now {
    if creation {
      save_create_connection_timeout()
      raise AdapterError(create_connection_timeout_message())
    } else {
      raise AdapterError(connection_timeout_message())
    }
  }
  @async.with_timeout((deadline - now).to_int(), run, error=ConnectionDeadline) catch {
    ConnectionDeadline =>
      if creation {
        save_create_connection_timeout()
        raise AdapterError(create_connection_timeout_message())
      } else {
        save_diagnostic(
          "connection-readiness",
          "timeout",
          error_type="readiness_timeout",
          timeout_ms=connection_timeout_ms(),
        )
        raise AdapterError(connection_timeout_message())
      }
    error => raise error
  }
}

///|
async fn save_create_connection_timeout() -> Unit {
  match create_recording.phase {
    "worktree-git-config" =>
      save_diagnostic(
        "configure-worktree-git",
        "timeout",
        error_type="git_config_timeout",
        timeout_ms=connection_timeout_ms(),
      )
    "worktree-git-fetch" =>
      save_diagnostic(
        "fetch-origin-branches",
        "timeout",
        error_type="git_fetch_timeout",
        timeout_ms=connection_timeout_ms(),
      )
    _ =>
      save_diagnostic(
        "connection-readiness",
        "timeout",
        error_type="readiness_timeout",
        timeout_ms=connection_timeout_ms(),
      )
  }
}

